{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Outcome-focused wellness coaching that builds resilient habits and simple frameworks for everyday life.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="aura-editorial">
  <header class="site-header">
    <div class="container header-grid">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <ul>
          <li><a href="/">Home</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="programs.html">Work With Me</a></li>
          <li><a href="services.html">Services</a></li>
          <li><a href="pricing.html">Pricing</a></li>
          <li><a href="testimonials.html">Stories</a></li>
          <li><a href="book.html">Book</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
      <button class="nav-toggle" aria-expanded="false" aria-controls="mobile-nav">Menu</button>
    </div>
    <nav id="mobile-nav" class="mobile-nav" hidden>
      <ul>
        <li><a href="/">Home</a></li>
        <li><a href="about.html">About</a></li>
        <li><a href="programs.html">Work With Me</a></li>
        <li><a href="services.html">Services</a></li>
        <li><a href="pricing.html">Pricing</a></li>
        <li><a href="testimonials.html">Stories</a></li>
        <li><a href="book.html">Book</a></li>
        <li><a href="contact.html">Contact</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <!-- HERO (editorial, high contrast) -->
    <section class="hero container" id="hero">
      <div class="hero-left">
        <h1 class="hero-title">Practical frameworks for healthier days — built around what you actually do.</h1>
        <p class="hero-sub">I’m {{COACH_NAME}} {{CREDENTIALS}} in {{CITY}}, {{STATE}}. I help busy people form reliable habits that create measurable energy, focus, and calm.</p>
        <div class="hero-ctas">
          <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <button class="btn btn-outline" id="leadmagnet-toggle">Free guide: 5 Daily Habits</button>
        </div>
        <form id="leadmagnet-form" class="leadmagnet" aria-hidden="true">
          <label for="lm-email">Get the guide</label>
          <input id="lm-email" type="email" placeholder="Email" required>
          <button class="btn" type="submit">Send me the guide</button>
          <p class="muted">No spam. You can unsubscribe anytime.</p>
        </form>
      </div>
      <div class="hero-right" aria-hidden="false">
        <img src="assets/img/hero.svg" alt="Illustration: steady steps toward wellbeing" class="hero-illustration">
      </div>
    </section>

    <!-- PILLARS (three editorial pillars) -->
    <section class="pillars container" id="pillars">
      <h2 class="section-heading">Three practical pillars I coach around</h2>
      <div class="pillar-grid">
        <article class="pillar">
          <svg class="icon" viewBox="0 0 64 64" aria-hidden="true"><rect x="8" y="8" width="48" height="48" rx="8" fill="#111"/></svg>
          <h3>Habit Structures</h3>
          <p>Design bite-sized routines tied to daily cues so small wins compound into reliable change.</p>
        </article>
        <article class="pillar">
          <svg class="icon" viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="24" fill="#111"/></svg>
          <h3>Energy Management</h3>
          <p>Simple frameworks to shape your day by aligning activities to natural energy rhythms.</p>
        </article>
        <article class="pillar">
          <svg class="icon" viewBox="0 0 64 64" aria-hidden="true"><path d="M8 32h48" stroke="#111" stroke-width="6" stroke-linecap="round"/></svg>
          <h3>Decision Simplicity</h3>
          <p>Reduce friction with rules-of-thumb so fewer willpower decisions drain your focus.</p>
        </article>
      </div>
    </section>

    <!-- MYTH vs TRUTH -->
    <section class="myth-truth container" id="myth-truth">
      <h2 class="section-heading">Common beliefs — and what really matters</h2>
      <div class="mt-grid">
        <div class="myths">
          <h4>Myths</h4>
          <ul>
            <li>Big transformations must be drastic.</li>
            <li>Motivation will carry you through.</li>
            <li>More info equals better results.</li>
          </ul>
        </div>
        <div class="truths">
          <h4>Truths</h4>
          <ul>
            <li>Small, repeatable actions outperform dramatic starts.</li>
            <li>Systems beat fleeting motivation; build routines not intensity.</li>
            <li>Clear frameworks + simple experiments produce steady gains.</li>
          </ul>
        </div>
      </div>
    </section>

    <!-- CASE STUDIES (outcomes-focused) -->
    <section class="case-studies container" id="case-studies">
      <h2 class="section-heading">Real changes, measured over time</h2>
      <div class="case-grid">
        <article class="case">
          <img class="avatar" src="assets/img/avatar.svg" alt="Client avatar">
          <h3>From overwhelmed to 3 hours deeper focus</h3>
          <p class="outcome">Within 10 weeks, a client reported a consistent two-hour morning focus block and 40% less evening rumination by applying the Focus Window Framework.</p>
          <a href="testimonials.html" class="read-more">Read the story</a>
        </article>
        <article class="case">
          <img class="avatar" src="assets/img/avatar.svg" alt="Client avatar">
          <h3>Sleep that sustains day-long energy</h3>
          <p class="outcome">Through habit scaffolding and environmental tweaks, clients shift bedtime routines and gain measurable improvements in afternoon energy.</p>
          <a href="testimonials.html" class="read-more">Read the story</a>
        </article>
      </div>
    </section>

    <!-- CALL TO ACTION -->
    <section class="cta container" id="cta-bottom">
      <div class="cta-inner">
        <h2>Start small. See measurable results.</h2>
        <p>Choose a guided pathway or a short exploration session to discover which habits move the needle for you.</p>
        <div class="cta-actions">
          <a class="btn btn-primary" href="programs.html">Explore programs</a>
          <a class="btn btn-outline" href="book.html">Schedule a free consult</a>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq container" id="faq">
      <h2 class="section-heading">Questions people ask before they start</h2>
      <div class="faq-grid">
        <div class="qa">
          <h4>How long before I notice a difference?</h4>
          <p>Most clients report clearer focus and at least one small routine that sticks within 3–6 weeks. Deeper change builds with steady practice.</p>
        </div>
        <div class="qa">
          <h4>Do you provide medical advice?</h4>
          <p>No. Coaching focuses on behaviors, habits, and practical frameworks. I do not provide medical or psychiatric treatment.</p>
        </div>
        <div class="qa">
          <h4>What if my schedule is unpredictable?</h4>
          <p>We design flexible micro-habits that adapt to variability. The goal is reliable progress, not perfection.</p>
        </div>
        <div class="qa">
          <h4>How do sessions work?</h4>
          <p>We run guided experiments: set a clear, testable habit, measure a simple metric, and iterate weekly.</p>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">{{TAGLINE}}</p>
        <p class="contact">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a><br>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav>
        <h4>Navigate</h4>
        <ul>
          <li><a href="/">Home</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="programs.html">Work With Me</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
      <div>
        <h4>Location</h4>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
    </div>
    <div class="legal">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}}. All rights reserved.</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
