{"path":"assets/css/styles.css","content":"/* Editorial, high contrast, bold scale (aura_editorial) */
:root{
  --bg:#ffffff; --text:#111111; --muted:#6b6b6b; --accent:#0a66ff; --accent-2:#111111; --gap:24px; --radius:10px;
  font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;
}
*{box-sizing:border-box}
body{margin:0;color:var(--text);background:var(--bg);line-height:1.5}
.container{max-width:1100px;margin:0 auto;padding:40px 20px}
.header-grid{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:800;font-size:1.1rem;color:var(--text);text-decoration:none}
.main-nav ul{display:flex;gap:18px;list-style:none;padding:0;margin:0}
.main-nav a{color:var(--muted);text-decoration:none}
.nav-toggle{display:none}

.hero{display:grid;grid-template-columns:1fr 420px;gap:40px;align-items:center;padding-top:30px;padding-bottom:30px}
.hero-title{font-size:2.2rem;line-height:1.03;margin:0 0 12px;font-weight:800}
.hero-sub{color:var(--muted);margin:0 0 18px}
.hero-ctas{display:flex;gap:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:8px;border:1px solid transparent;background:transparent;text-decoration:none;color:var(--accent-2);cursor:pointer}
.btn-primary{background:var(--accent);color:#fff}
.btn-outline{border-color:var(--accent);color:var(--accent)}
.leadmagnet{margin-top:18px;display:none;gap:8px}
.leadmagnet input{padding:10px;border-radius:8px;border:1px solid #ddd;width:220px}
.muted{color:var(--muted);font-size:0.9rem}
.hero-illustration{width:100%;height:auto;border-radius:12px;display:block}

.section-heading{font-size:1.15rem;font-weight:700;margin:0 0 18px}
.pillar-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.pillar{background:#f8f9ff;padding:18px;border-radius:12px}
.pillar h3{margin:12px 0 8px}
.icon{width:48px;height:48px}

.myth-truth .mt-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.myths, .truths{background:#fff8f3;padding:18px;border-radius:12px}

.case-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}
.case{background:#f4fbff;padding:18px;border-radius:12px}
.avatar{width:56px;height:56px;border-radius:8px}
.read-more{display:inline-block;margin-top:10px;color:var(--accent)}

.cta{background:linear-gradient(180deg,#0a66ff 0%,#083f9a 100%);color:#fff;border-radius:12px;padding:28px}
.cta .btn-outline{background:transparent;border-color:#fff;color:#fff}

.faq-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}
.qa h4{margin:0 0 8px}

.site-footer{background:#111;color:#fff;padding-top:30px}
.footer-grid{display:grid;grid-template-columns:1fr 180px 160px;gap:20px}
.footer-grid a{color:#fff;text-decoration:none}
.legal{padding:18px 20px;border-top:1px solid rgba(255,255,255,0.06);text-align:center;color:#bbb}

/* Responsive */
@media(max-width:900px){
  .hero{grid-template-columns:1fr;}
  .pillar-grid{grid-template-columns:1fr}
  .case-grid{grid-template-columns:1fr}
  .faq-grid{grid-template-columns:1fr}
  .main-nav{display:none}
  .nav-toggle{display:inline-block}
  #mobile-nav{display:block}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  const toggle = document.querySelector('.nav-toggle');
  const mobileNav = document.getElementById('mobile-nav');
  toggle && toggle.addEventListener('click', ()=>{
    const expanded = toggle.getAttribute('aria-expanded') === 'true';
    toggle.setAttribute('aria-expanded', String(!expanded));
    if(!expanded){ mobileNav.hidden = false } else { mobileNav.hidden = true }
  });

  // Lead magnet reveal & simple submit
  const lmToggle = document.getElementById('leadmagnet-toggle');
  const lmForm = document.getElementById('leadmagnet-form');
  const lmEmail = document.getElementById('lm-email');
  if(lmToggle){
    lmToggle.addEventListener('click', ()=>{
      const shown = lmForm.style.display === 'grid' || lmForm.getAttribute('aria-hidden') === 'false';
      lmForm.style.display = shown ? 'none' : 'grid';
      lmForm.setAttribute('aria-hidden', String(shown));
      if(!shown) lmEmail.focus();
    });
  }
  if(lmForm){
    lmForm.addEventListener('submit', (e)=>{
      e.preventDefault();
      const email = lmEmail.value.trim();
      if(!email) return alert('Please add an email');
      // Pretend to send; in production hook to an API
      lmForm.innerHTML = '<p class="muted">Thanks! Check your inbox for the guide.</p>';
      console.log('lead magnet signup', email);
    });
  }

  // Footer year
  const year = document.getElementById('year');
  if(year) year.textContent = new Date().getFullYear();

  // Smooth in-page links
  document.querySelectorAll('a[href^="#"]').forEach(a=>{
    a.addEventListener('click', (e)=>{
      const id = a.getAttribute('href').slice(1);
      const el = document.getElementById(id);
      if(el){ e.preventDefault(); el.scrollIntoView({behavior:'smooth'}); }
    });
  });
})();
"} 
